    static readonly Dictionary<string, (Geometry, Brush)?> Cache = new();

    public static (Geometry Geometry, Brush Brush)? For(string id)
    {
        if (Cache.TryGetValue(id, out var hit)) return hit;
        (Geometry, Brush)? r = null;
        if (Data.TryGetValue(id, out var d))
        {
            var g = Geometry.Parse(d.Path);
            g.Freeze();
            var b = new SolidColorBrush((Color)ColorConverter.ConvertFromString(d.Color));
            b.Freeze();
            r = (g, b);
        }
        return Cache[id] = r;
    }
